// Shape of src/data/gamedata.json (generated by scripts/wiki/build.mjs).

export type Dlc = "BaseGame" | "DLC1" | "DLC2" | "DLC3" | "DLC4" | "DLC5";

export interface Range {
  min: number;
  max: number;
}

export interface Location {
  name: string;
  dlc: Dlc;
  rareCustomers: string[];
}

export interface Ingredient {
  name: string;
  /** Path under public/, or null when the wiki has no image. */
  image: string | null;
  dlc: Dlc;
  category: string;
  level: number;
  price: number;
  tags: string[];
}

export interface Beverage {
  name: string;
  image: string | null;
  /** Collaboration id when only that collaboration provides it; null otherwise. */
  collab: string | null;
  dlc: Dlc;
  level: number;
  price: number;
  alcohol: string | null;
  tags: string[];
}

export interface Recipe {
  name: string;
  image: string | null;
  collab: string | null;
  dlc: Dlc;
  level: number;
  price: number;
  tags: string[];
  bannedTags: string[];
  ingredients: string[];
  cookware: string;
  cookTime: number;
}

export interface NormalCustomer {
  name: string;
  image: string | null;
  dlc: Dlc;
  locations: string[];
  likesAllTags: boolean;
  undocumented: boolean;
  likedFoodTags: string[];
  likedDrinkTags: string[];
  description: string;
}

/** What a rare customer says in-game when requesting a food tag (from the wiki's Tag Requests section). */
export interface TagQuote {
  tag: string;
  text: string;
  /** e.g. "DLC 4" when the wiki lists different lines per game version; null otherwise. */
  variant: string | null;
}

/** A rare customer's spell card, from the wiki's Spell Card section (English). */
export interface SpellCard {
  name: string;
  /** reward: triggered by a pink rating; punishment: by a black rating. */
  kind: "reward" | "punishment" | "follow-up";
  /** Description paragraphs, bullet points and sub-effect headings, in order. */
  blocks: { type: "p" | "li" | "h"; text: string }[];
}

export interface RareCustomer {
  name: string;
  collab: string | null;
  foodQuotes: TagQuote[];
  spellCards: SpellCard[];
  /** The wiki's note when a guest has no spell cards; null otherwise. */
  spellCardNote: string | null;
  image: string | null;
  shortName: string;
  kind: "rare" | "special";
  dlc: Dlc | null;
  homeLocation: string | null;
  budget: Range | null;
  locations: string[];
  undocumented: boolean;
  likedFoodTags: string[];
  dislikedFoodTags: string[];
  likedDrinkTags: string[];
}

export interface MerchantItem {
  name: string;
  type: string;
  probability: number;
  amount: Range | null;
}

export interface Merchant {
  name: string;
  dlc: Dlc;
  location: string | null;
  priceMultiplier: Range | null;
  items: MerchantItem[];
}

export interface Partner {
  name: string;
  shortName: string;
  dlc: Dlc;
  movementSpeed: string;
  workSpeed: string;
  revenueShare: number;
}

/** Crossover content enabled at the collaboration terminal next to Mystia's house. */
export interface Collaboration {
  id: string;
  name: string;
  customers: string[];
  recipes: string[];
  beverages: string[];
}

export interface GameData {
  meta: { source: string; fetchedAt: string; builtAt: string; dlcs: Dlc[] };
  locations: Location[];
  cookware: { name: string; image: string | null }[];
  collaborations: Collaboration[];
  ingredients: Ingredient[];
  beverages: Beverage[];
  recipes: Recipe[];
  normalCustomers: NormalCustomer[];
  rareCustomers: RareCustomer[];
  merchants: Merchant[];
  partners: Partner[];
  tags: { food: string[]; drink: string[] };
}
